gical"},{"name":"Storekeeping","description":"Calculates how grain reserves and shipment schedules can support people through disruption.","category":"mental"}]}],"relationships":[{"id":"rel_tamsin_ren","source_character_id":"chr_tamsin_vell","target_character_id":"chr_ren_calder","relationship_type":"rival","description":"Tamsin Vell distrusts Ren Calder's Cartel ties and blames toll decisions for delaying bridge inspections; Ren resents her assumption that Wardens should control access without accounting for shipping costs."},{"id":"rel_ren_tamsin","source_character_id":"chr_ren_calder","target_character_id":"chr_tamsin_vell","relationship_type":"ally","description":"Ren Calder and Tamsin Vell reluctantly work together when the shared safety of the routes becomes more urgent than their dispute over tolls and authority."},{"id":"rel_ilyra_tamsin","source_character_id":"chr_ilyra_senn","target_character_id":"chr_tamsin_vell","relationship_type":"colleague","description":"Ilyra Senn and Tamsin Vell share Bridge Warden responsibilities, but Ilyra's maps sometimes contradict Tamsin's inspection records, forcing both to question their assumptions."},{"id":"rel_maelin_ren","source_character_id":"chr_maelin_ro","target_character_id":"chr_ren_calder","relationship_type":"rival","description":"Maelin Ro opposes Ren Calder's Cartel levy on grain, while Ren must negotiate with her to keep food moving through Mistral Docks."},{"id":"rel_maelin_ilyra","source_character_id":"chr_maelin_ro","target_character_id":"chr_ilyra_senn","relationship_type":"ally","description":"Maelin Ro relies on Ilyra Senn's changing-route charts to plan grain shipments, and Ilyra depends on Maelin's practical reports to correct her maps."}]}
